// CSU_C12 - Update/correction of patient order/result information
// Data are entered in the clinical trials system or may reside in laboratory, pathology, radiology, pharmacy and/or other clinical applications.  Most clinical trials data - clinical observations and study variables - will be communicated in OBR and OBX segments.  The CSR, CSP, and CSS segments will identify the specific association these OBR and OBX have to the clinical trial.  Data can be broadcast or transmitted in batch mode to study sponsors or the data management center for collaborative studies.
type CSU_C12 struct {
	MSH     *MSH              `hl7:"MSH,required"`
	SFT     []SFT             `hl7:"SFT"`
	PATIENT []CSU_C12_PATIENT `hl7:"PATIENT,required"`
}

func NewCSU_C12() *CSU_C12 {
	return &CSU_C12{
		MSH: NewMSH(NewMSG().SetMessageCode("CSU").SetTriggerEvent("C12").SetMessageStructure("CSU_C12")),
	}
}

func (m *CSU_C12) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("CSU_C12.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("CSU_C12.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("CSU_C12.SFT: %w", err)
		}
	}

	if len(m.PATIENT) == 0 {
		return fmt.Errorf("CSU_C12.PATIENT is required")
	}
	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("CSU_C12.PATIENT: %w", err)
		}
	}
	return nil
}

