// DFT_P03 - Post Detail Financial Transactions
// The Detail Financial Transaction (DFT) message is used to describe a financial transaction transmitted between systems, that is, to the billing system for ancillary charges, ADT to billing system for patient deposits, etc.
//
// Note:  The ROL segment is optionally included after the PD1 to transmit information for patient level primary care providers, after the PV2 for additional information on the physicians whose information is sent there (i.e. Attending Doctor, Referring Doctor, Consulting Doctor), and within the insurance construct to transmit information for insurance level primary care providers.
//
// Note:  There is an information overlap between the FT1, DG1 and PR1 segments.  If diagnosis information is sent in an FT1 segment, it should be consistent with the information contained in any DG1 segments present within its hierarchy. Since the procedure code field within the FT1 does not repeat, if procedure information is sent on an FT1 it is recommended that the single occurrence of the code in FT1 equates to the primary procedure (PR1-14 - Procedure Priority code value 1).
//
// Note:  The extra set of DG1/DRG/GT1/IN1/IN2/IN3/ROL segments added in V2.4 has been withdrawn as a technical correction
type DFT_P03 struct {
	MSH         *MSH                  `hl7:"MSH,required"`
	SFT         []SFT                 `hl7:"SFT"`
	EVN         *EVN                  `hl7:"EVN,required"`
	PID         *PID                  `hl7:"PID,required"`
	PD1         *PD1                  `hl7:"PD1"`
	ROL         []ROL                 `hl7:"ROL"`
	PV1         *PV1                  `hl7:"PV1"`
	PV2         *PV2                  `hl7:"PV2"`
	ROL_1       []ROL                 `hl7:"ROL"`
	DB1         []DB1                 `hl7:"DB1"`
	COMMONORDER []DFT_P03_COMMONORDER `hl7:"COMMON ORDER"`
	FINANCIAL   []DFT_P03_FINANCIAL   `hl7:"FINANCIAL,required"`
	DG1         []DG1                 `hl7:"DG1"`
	DRG         *DRG                  `hl7:"DRG"`
	GT1         []GT1                 `hl7:"GT1"`
	INSURANCE   []DFT_P03_INSURANCE   `hl7:"INSURANCE"`
	ACC         *ACC                  `hl7:"ACC"`
}

func NewDFT_P03() *DFT_P03 {
	return &DFT_P03{
		MSH: NewMSH(NewMSG().SetMessageCode("DFT").SetTriggerEvent("P03").SetMessageStructure("DFT_P03")),
	}
}

func (m *DFT_P03) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("DFT_P03.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.SFT: %w", err)
		}
	}

	if m.EVN == nil {
		return fmt.Errorf("DFT_P03.EVN is required")
	}
	if m.EVN != nil {
		if err := m.EVN.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.EVN: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("DFT_P03.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.PID: %w", err)
		}
	}

	if m.PD1 != nil {
		if err := m.PD1.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.PD1: %w", err)
		}
	}

	for _, item := range m.ROL {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.ROL: %w", err)
		}
	}

	if m.PV1 != nil {
		if err := m.PV1.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.PV1: %w", err)
		}
	}

	if m.PV2 != nil {
		if err := m.PV2.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.PV2: %w", err)
		}
	}

	for _, item := range m.ROL_1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.ROL_1: %w", err)
		}
	}

	for _, item := range m.DB1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.DB1: %w", err)
		}
	}

	for _, item := range m.COMMONORDER {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.COMMONORDER: %w", err)
		}
	}

	if len(m.FINANCIAL) == 0 {
		return fmt.Errorf("DFT_P03.FINANCIAL is required")
	}
	for _, item := range m.FINANCIAL {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.FINANCIAL: %w", err)
		}
	}

	for _, item := range m.DG1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.DG1: %w", err)
		}
	}

	if m.DRG != nil {
		if err := m.DRG.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.DRG: %w", err)
		}
	}

	for _, item := range m.GT1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.GT1: %w", err)
		}
	}

	for _, item := range m.INSURANCE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.INSURANCE: %w", err)
		}
	}

	if m.ACC != nil {
		if err := m.ACC.Validate(); err != nil {
			return fmt.Errorf("DFT_P03.ACC: %w", err)
		}
	}
	return nil
}

