// DFT_P11 - Post Detail Financial Transactions - Expanded
// The Detail Financial Transaction (DFT) - Expanded message is used to describe a financial transaction transmitted between systems, that is, to the billing system for ancillary charges, ADT to billing system for patient deposits, etc.  It serves the same function as the Post Detail Financial Transactions (event P03) message, but also supports the use cases described below.
//
// Use case for adding the INx and GT1 segments inside the FT1 repetition:
//
// If the insurance and/or the guarantor information is specific to a certain financial transaction of a patient and differs from the patient's regular insurance and/or guarantor, you may use the INx and GT1 segments related to the FT1 segment. If being used, the information supersedes the information on the patient level.
//
// Note:  The ROL segment is optionally included after the PD1 to transmit information for patient level primary care providers, after the PV2 for additional information on the physicians whose information is sent there (i.e. Attending Doctor, Referring Doctor, Consulting Doctor), and within the insurance construct to transmit information for insurance level primary care providers.
//
// Note:  There is an information overlap between the FT1, DG1 and PR1 segments.  If diagnosis information is sent in an FT1 segment, it should be consistent with the information contained in any DG1 segments present within its hierarchy. Since the procedure code field within the FT1 does not repeat, if procedure information is sent on an FT1 it is recommended that the single occurrence of the code in FT1 equates to the primary procedure (PR1-14 - Procedure Priority code value 1).
type DFT_P11 struct {
	MSH         *MSH                  `hl7:"MSH,required"`
	SFT         []SFT                 `hl7:"SFT"`
	EVN         *EVN                  `hl7:"EVN,required"`
	PID         *PID                  `hl7:"PID,required"`
	PD1         *PD1                  `hl7:"PD1"`
	ROL         []ROL                 `hl7:"ROL"`
	PV1         *PV1                  `hl7:"PV1"`
	PV2         *PV2                  `hl7:"PV2"`
	ROL_1       []ROL                 `hl7:"ROL"`
	DB1         []DB1                 `hl7:"DB1"`
	COMMONORDER []DFT_P11_COMMONORDER `hl7:"COMMON ORDER"`
	DG1         []DG1                 `hl7:"DG1"`
	DRG         *DRG                  `hl7:"DRG"`
	GT1         []GT1                 `hl7:"GT1"`
	INSURANCE   []DFT_P11_INSURANCE   `hl7:"INSURANCE"`
	ACC         *ACC                  `hl7:"ACC"`
	FINANCIAL   []DFT_P11_FINANCIAL   `hl7:"FINANCIAL,required"`
}

func NewDFT_P11() *DFT_P11 {
	return &DFT_P11{
		MSH: NewMSH(NewMSG().SetMessageCode("DFT").SetTriggerEvent("P11").SetMessageStructure("DFT_P11")),
	}
}

func (m *DFT_P11) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("DFT_P11.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.SFT: %w", err)
		}
	}

	if m.EVN == nil {
		return fmt.Errorf("DFT_P11.EVN is required")
	}
	if m.EVN != nil {
		if err := m.EVN.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.EVN: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("DFT_P11.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.PID: %w", err)
		}
	}

	if m.PD1 != nil {
		if err := m.PD1.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.PD1: %w", err)
		}
	}

	for _, item := range m.ROL {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.ROL: %w", err)
		}
	}

	if m.PV1 != nil {
		if err := m.PV1.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.PV1: %w", err)
		}
	}

	if m.PV2 != nil {
		if err := m.PV2.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.PV2: %w", err)
		}
	}

	for _, item := range m.ROL_1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.ROL_1: %w", err)
		}
	}

	for _, item := range m.DB1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.DB1: %w", err)
		}
	}

	for _, item := range m.COMMONORDER {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.COMMONORDER: %w", err)
		}
	}

	for _, item := range m.DG1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.DG1: %w", err)
		}
	}

	if m.DRG != nil {
		if err := m.DRG.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.DRG: %w", err)
		}
	}

	for _, item := range m.GT1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.GT1: %w", err)
		}
	}

	for _, item := range m.INSURANCE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.INSURANCE: %w", err)
		}
	}

	if m.ACC != nil {
		if err := m.ACC.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.ACC: %w", err)
		}
	}

	if len(m.FINANCIAL) == 0 {
		return fmt.Errorf("DFT_P11.FINANCIAL is required")
	}
	for _, item := range m.FINANCIAL {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("DFT_P11.FINANCIAL: %w", err)
		}
	}
	return nil
}

