// OML_O21 - Laboratory Order
// The following message structure may be used for the communication of laboratory and other order messages and must be used for lab automation messages where it is required that the Specimen/Container information is within the ORC/OBR segment group.  While the ORM message with the OBR segment can be used for backwards compatibility for general lab messages, only the OML message should be used to take advantage of the specimen and container extensions required in laboratory automation.
//
// The trigger event for this message is any change to a laboratory order.  Such changes include submission of new orders, cancellations, updates, etc.  OML messages can originate also with a placer, filler, or an interested third party
type OML_O21 struct {
	MSH     *MSH             `hl7:"MSH,required"`
	SFT     []SFT            `hl7:"SFT"`
	NTE     []NTE            `hl7:"NTE"`
	PATIENT *OML_O21_PATIENT `hl7:"PATIENT"`
	ORDER   []OML_O21_ORDER  `hl7:"ORDER,required"`
}

func NewOML_O21() *OML_O21 {
	return &OML_O21{
		MSH: NewMSH(NewMSG().SetMessageCode("OML").SetTriggerEvent("O21").SetMessageStructure("OML_O21")),
	}
}

func (m *OML_O21) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OML_O21.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OML_O21.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O21.SFT: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O21.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OML_O21.PATIENT: %w", err)
		}
	}

	if len(m.ORDER) == 0 {
		return fmt.Errorf("OML_O21.ORDER is required")
	}
	for _, item := range m.ORDER {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O21.ORDER: %w", err)
		}
	}
	return nil
}

func (m *OML_O21) SetMSH(v *MSH) *OML_O21 {
	m.MSH = v
	return m
}

func (m *OML_O21) AddSFT(v SFT) *OML_O21 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *OML_O21) AddNTE(v NTE) *OML_O21 {
	m.NTE = append(m.NTE, v)
	return m
}

func (m *OML_O21) SetPATIENT(v *OML_O21_PATIENT) *OML_O21 {
	m.PATIENT = v
	return m
}

func (m *OML_O21) AddORDER(v OML_O21_ORDER) *OML_O21 {
	m.ORDER = append(m.ORDER, v)
	return m
}

