// OML_O33 - Laboratory Order for Multiple Orders Related to a Single Specimen
// The trigger event for this message is any change to a laboratory order.  Such changes include submission of new orders, cancellations, updates, etc where multiple orders are associated with a single sample which may be carried in multiple containers.  OML messages can originate also with a placer, filler, or an interested third party.
//
// # This allows for a Specimen-centric message with multiple orders per specimen grouped by the specimen
//
// The following message structure may be used for the communication of laboratory and other order messages and must be used for lab automation messages where the message requires Specimen/container information to group a number of orders.  While the ORM message with the OBR segment can be used for backwards compatibility for general lab messages, only the OML message should be used to take advantage of the specimen and container extensions required in laboratory automation.
type OML_O33 struct {
	MSH      *MSH               `hl7:"MSH,required"`
	SFT      []SFT              `hl7:"SFT"`
	NTE      []NTE              `hl7:"NTE"`
	PATIENT  *OML_O33_PATIENT   `hl7:"PATIENT"`
	SPECIMEN []OML_O33_SPECIMEN `hl7:"SPECIMEN,required"`
}

func NewOML_O33() *OML_O33 {
	return &OML_O33{
		MSH: NewMSH(NewMSG().SetMessageCode("OML").SetTriggerEvent("O33").SetMessageStructure("OML_O33")),
	}
}

func (m *OML_O33) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OML_O33.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OML_O33.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O33.SFT: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O33.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OML_O33.PATIENT: %w", err)
		}
	}

	if len(m.SPECIMEN) == 0 {
		return fmt.Errorf("OML_O33.SPECIMEN is required")
	}
	for _, item := range m.SPECIMEN {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O33.SPECIMEN: %w", err)
		}
	}
	return nil
}

func (m *OML_O33) SetMSH(v *MSH) *OML_O33 {
	m.MSH = v
	return m
}

func (m *OML_O33) AddSFT(v SFT) *OML_O33 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *OML_O33) AddNTE(v NTE) *OML_O33 {
	m.NTE = append(m.NTE, v)
	return m
}

