// This message is kept here for backward compatibility reasons only. The new OUL messages with additional triggers should be used, when the Specimen information (segment SPM) with or without Container information (segment SAC) is required.
type OUL_R21 struct {
	MSH              *MSH                       `hl7:"MSH,required"`
	SFT              []SFT                      `hl7:"SFT"`
	NTE              *NTE                       `hl7:"NTE"`
	PATIENT          *OUL_R21_PATIENT           `hl7:"PATIENT"`
	VISIT            *OUL_R21_VISIT             `hl7:"VISIT"`
	ORDEROBSERVATION []OUL_R21_ORDEROBSERVATION `hl7:"ORDER OBSERVATION,required"`
	DSC              *DSC                       `hl7:"DSC"`
}

func NewOUL_R21() *OUL_R21 {
	return &OUL_R21{
		MSH: NewMSH(NewMSG().SetMessageCode("OUL").SetTriggerEvent("R21").SetMessageStructure("OUL_R21")),
	}
}

func (m *OUL_R21) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OUL_R21.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.SFT: %w", err)
		}
	}

	if m.NTE != nil {
		if err := m.NTE.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.PATIENT: %w", err)
		}
	}

	if m.VISIT != nil {
		if err := m.VISIT.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.VISIT: %w", err)
		}
	}

	if len(m.ORDEROBSERVATION) == 0 {
		return fmt.Errorf("OUL_R21.ORDEROBSERVATION is required")
	}
	for _, item := range m.ORDEROBSERVATION {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.ORDEROBSERVATION: %w", err)
		}
	}

	if m.DSC != nil {
		if err := m.DSC.Validate(); err != nil {
			return fmt.Errorf("OUL_R21.DSC: %w", err)
		}
	}
	return nil
}

