	if m.MSH == nil {
		return fmt.Errorf("OUL_R22.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.SFT: %w", err)
		}
	}

	if m.NTE != nil {
		if err := m.NTE.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.PATIENT: %w", err)
		}
	}

	if m.VISIT != nil {
		if err := m.VISIT.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.VISIT: %w", err)
		}
	}

	if len(m.SPECIMEN) == 0 {
		return fmt.Errorf("OUL_R22.SPECIMEN is required")
	}
	for _, item := range m.SPECIMEN {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.SPECIMEN: %w", err)
		}
	}

	if m.DSC != nil {
		if err := m.DSC.Validate(); err != nil {
			return fmt.Errorf("OUL_R22.DSC: %w", err)
		}
	}
	return nil
