// PPP_PCC - Pathway (problem-oriented) update
type PPP_PCC struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPP_PCC_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PATHWAY      []PPP_PCC_PATHWAY     `hl7:"PATHWAY,required"`
}

func NewPPP_PCC() *PPP_PCC {
	return &PPP_PCC{
		MSH: NewMSH(NewMSG().SetMessageCode("PPP").SetTriggerEvent("PCC").SetMessageStructure("PPP_PCC")),
	}
}

func (m *PPP_PCC) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPP_PCC.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPP_PCC.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCC.SFT: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPP_PCC.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPP_PCC.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPP_PCC.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PATHWAY) == 0 {
		return fmt.Errorf("PPP_PCC.PATHWAY is required")
	}
	for _, item := range m.PATHWAY {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCC.PATHWAY: %w", err)
		}
	}
	return nil
}

func (m *PPP_PCC) SetMSH(v *MSH) *PPP_PCC {
	m.MSH = v
	return m
}

func (m *PPP_PCC) AddSFT(v SFT) *PPP_PCC {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *PPP_PCC) SetPID(v *PID) *PPP_PCC {
	m.PID = v
	return m
}

func (m *PPP_PCC) SetPATIENTVISIT(v *PPP_PCC_PATIENTVISIT) *PPP_PCC {
	m.PATIENTVISIT = v
	return m
}

func (m *PPP_PCC) AddPATHWAY(v PPP_PCC_PATHWAY) *PPP_PCC {
	m.PATHWAY = append(m.PATHWAY, v)
	return m
}

