type PPP_PCD struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPP_PCD_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PATHWAY      []PPP_PCD_PATHWAY     `hl7:"PATHWAY,required"`
}

func NewPPP_PCD() *PPP_PCD {
	return &PPP_PCD{
		MSH: NewMSH(NewMSG().SetMessageCode("PPP").SetTriggerEvent("PCD").SetMessageStructure("PPP_PCD")),
	}
}

func (m *PPP_PCD) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPP_PCD.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPP_PCD.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCD.SFT: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPP_PCD.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPP_PCD.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPP_PCD.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PATHWAY) == 0 {
		return fmt.Errorf("PPP_PCD.PATHWAY is required")
	}
	for _, item := range m.PATHWAY {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCD.PATHWAY: %w", err)
		}
	}
	return nil
}

func (m *PPP_PCD) SetMSH(v *MSH) *PPP_PCD {
	m.MSH = v
	return m
}

