// PPR_PC1 - Problem add
// The patient problem message is used to send problems from one application to another (e.g., a point of care system to a clinical repository).  Many of the segments associated with this event are optional.  This optionality allows systems in need of this information to set up transactions that fulfill their requirements
type PPR_PC1 struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPR_PC1_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PROBLEM      []PPR_PC1_PROBLEM     `hl7:"PROBLEM,required"`
}

func NewPPR_PC1() *PPR_PC1 {
	return &PPR_PC1{
		MSH: NewMSH(NewMSG().SetMessageCode("PPR").SetTriggerEvent("PC1").SetMessageStructure("PPR_PC1")),
	}
}

func (m *PPR_PC1) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPR_PC1.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPR_PC1.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC1.SFT: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPR_PC1.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPR_PC1.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPR_PC1.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PROBLEM) == 0 {
		return fmt.Errorf("PPR_PC1.PROBLEM is required")
	}
	for _, item := range m.PROBLEM {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC1.PROBLEM: %w", err)
		}
	}
	return nil
}

