// PPR_PC2 - Problem update
// The patient problem message is used to send problems from one application to another (e.g., a point of care system to a clinical repository).  Many of the segments associated with this event are optional.  This optionality allows systems in need of this information to set up transactions that fulfill their requirements
type PPR_PC2 struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPR_PC2_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PROBLEM      []PPR_PC2_PROBLEM     `hl7:"PROBLEM,required"`
}

func NewPPR_PC2() *PPR_PC2 {
	return &PPR_PC2{
		MSH: NewMSH(NewMSG().SetMessageCode("PPR").SetTriggerEvent("PC2").SetMessageStructure("PPR_PC2")),
	}
}

func (m *PPR_PC2) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPR_PC2.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPR_PC2.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC2.SFT: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPR_PC2.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPR_PC2.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPR_PC2.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PROBLEM) == 0 {
		return fmt.Errorf("PPR_PC2.PROBLEM is required")
	}
	for _, item := range m.PROBLEM {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC2.PROBLEM: %w", err)
		}
	}
	return nil
}

func (m *PPR_PC2) SetMSH(v *MSH) *PPR_PC2 {
	m.MSH = v
	return m
}

func (m *PPR_PC2) AddSFT(v SFT) *PPR_PC2 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *PPR_PC2) SetPID(v *PID) *PPR_PC2 {
	m.PID = v
	return m
}

func (m *PPR_PC2) SetPATIENTVISIT(v *PPR_PC2_PATIENTVISIT) *PPR_PC2 {
	m.PATIENTVISIT = v
	return m
}

