// PPR_PC3 - Problem delete
// The patient problem message is used to send problems from one application to another (e.g., a point of care system to a clinical repository).  Many of the segments associated with this event are optional.  This optionality allows systems in need of this information to set up transactions that fulfill their requirements
type PPR_PC3 struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPR_PC3_PATIENTVISIT `hl7:"PATIENT VISIT"`
	PROBLEM      []PPR_PC3_PROBLEM     `hl7:"PROBLEM,required"`
}

func NewPPR_PC3() *PPR_PC3 {
	return &PPR_PC3{
		MSH: NewMSH(NewMSG().SetMessageCode("PPR").SetTriggerEvent("PC3").SetMessageStructure("PPR_PC3")),
	}
}

func (m *PPR_PC3) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPR_PC3.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPR_PC3.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC3.SFT: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPR_PC3.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPR_PC3.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPR_PC3.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PROBLEM) == 0 {
		return fmt.Errorf("PPR_PC3.PROBLEM is required")
	}
	for _, item := range m.PROBLEM {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPR_PC3.PROBLEM: %w", err)
		}
	}
	return nil
}

func (m *PPR_PC3) SetMSH(v *MSH) *PPR_PC3 {
	m.MSH = v
	return m
}

func (m *PPR_PC3) AddSFT(v SFT) *PPR_PC3 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *PPR_PC3) SetPID(v *PID) *PPR_PC3 {
	m.PID = v
	return m
}

func (m *PPR_PC3) SetPATIENTVISIT(v *PPR_PC3_PATIENTVISIT) *PPR_PC3 {
	m.PATIENTVISIT = v
	return m
}

