// SRM_S09 - Schedule request - Cancellation of service/resource on appointment
// This trigger event requests that a service or resource be removed from an existing scheduled appointment that has not yet begun.  A cancel event is used to stop a valid service or resource from participating in the appointment.  For example, if a portable X-ray machine scheduled for an exam is no longer needed, then the placer application requests that the resource be canceled on the filler application.  This trigger event should only be used for appointments that have not been completed, or for parent appointments whose children have not been completed.  If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the modified appointment
type SRM_S09 struct {
	MSH       *MSH                `hl7:"MSH,required"`
	ARQ       *ARQ                `hl7:"ARQ,required"`
	APR       *APR                `hl7:"APR"`
	NTE       []NTE               `hl7:"NTE"`
	PATIENT   []SRM_S09_PATIENT   `hl7:"PATIENT"`
	RESOURCES []SRM_S09_RESOURCES `hl7:"RESOURCES,required"`
}

func NewSRM_S09() *SRM_S09 {
	return &SRM_S09{
		MSH: NewMSH(NewMSG().SetMessageCode("SRM").SetTriggerEvent("S09").SetMessageStructure("SRM_S09")),
	}
}

func (m *SRM_S09) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRM_S09.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.MSH: %w", err)
		}
	}

	if m.ARQ == nil {
		return fmt.Errorf("SRM_S09.ARQ is required")
	}
	if m.ARQ != nil {
		if err := m.ARQ.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.ARQ: %w", err)
		}
	}

	if m.APR != nil {
		if err := m.APR.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.APR: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.NTE: %w", err)
		}
	}

	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.PATIENT: %w", err)
		}
	}

	if len(m.RESOURCES) == 0 {
		return fmt.Errorf("SRM_S09.RESOURCES is required")
	}
	for _, item := range m.RESOURCES {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S09.RESOURCES: %w", err)
		}
	}
	return nil
}

func (m *SRM_S09) SetMSH(v *MSH) *SRM_S09 {
	m.MSH = v
	return m
}

func (m *SRM_S09) SetARQ(v *ARQ) *SRM_S09 {
	m.ARQ = v
	return m
}

func (m *SRM_S09) SetAPR(v *APR) *SRM_S09 {
	m.APR = v
	return m
}

func (m *SRM_S09) AddNTE(v NTE) *SRM_S09 {
	m.NTE = append(m.NTE, v)
	return m
}

func (m *SRM_S09) AddPATIENT(v SRM_S09_PATIENT) *SRM_S09 {
	m.PATIENT = append(m.PATIENT, v)
	return m
}

