// VXQ_V01 - Vaccination Record Query
// When an immunization registry does not already have the complete patient vaccination record, it will send a query (with a V01 event) for the definitive (last updated) record.
type VXQ_V01 struct {
	MSH *MSH  `hl7:"MSH,required"`
	SFT []SFT `hl7:"SFT"`
	QRD *QRD  `hl7:"QRD,required"`
	QRF *QRF  `hl7:"QRF"`
}

func NewVXQ_V01() *VXQ_V01 {
	return &VXQ_V01{
		MSH: NewMSH(NewMSG().SetMessageCode("VXQ").SetTriggerEvent("V01").SetMessageStructure("VXQ_V01")),
	}
}

func (m *VXQ_V01) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("VXQ_V01.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("VXQ_V01.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("VXQ_V01.SFT: %w", err)
		}
	}

	if m.QRD == nil {
		return fmt.Errorf("VXQ_V01.QRD is required")
	}
	if m.QRD != nil {
		if err := m.QRD.Validate(); err != nil {
			return fmt.Errorf("VXQ_V01.QRD: %w", err)
		}
	}

	if m.QRF != nil {
		if err := m.QRF.Validate(); err != nil {
			return fmt.Errorf("VXQ_V01.QRF: %w", err)
		}
	}
	return nil
}

func (m *VXQ_V01) SetMSH(v *MSH) *VXQ_V01 {
	m.MSH = v
	return m
}

func (m *VXQ_V01) AddSFT(v SFT) *VXQ_V01 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *VXQ_V01) SetQRD(v *QRD) *VXQ_V01 {
	m.QRD = v
	return m
}

func (m *VXQ_V01) SetQRF(v *QRF) *VXQ_V01 {
	m.QRF = v
	return m
}

