// VXR_V03 - Vaccination Record Response
// When the patient has been uniquely identified (there is only one "match" to the query), the response to the query (with a V03 event) will follow this format.
type VXR_V03 struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	MSA          *MSA                  `hl7:"MSA,required"`
	SFT          []SFT                 `hl7:"SFT"`
	QRD          *QRD                  `hl7:"QRD,required"`
	QRF          *QRF                  `hl7:"QRF"`
	PID          *PID                  `hl7:"PID,required"`
	PD1          *PD1                  `hl7:"PD1"`
	NK1          []NK1                 `hl7:"NK1"`
	PATIENTVISIT *VXR_V03_PATIENTVISIT `hl7:"PATIENT VISIT"`
	GT1          []GT1                 `hl7:"GT1"`
	INSURANCE    []VXR_V03_INSURANCE   `hl7:"INSURANCE"`
	ORDER        []VXR_V03_ORDER       `hl7:"ORDER"`
}

func NewVXR_V03() *VXR_V03 {
	return &VXR_V03{
		MSH: NewMSH(NewMSG().SetMessageCode("VXR").SetTriggerEvent("V03").SetMessageStructure("VXR_V03")),
	}
}

